#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: segredos do CI de lojas do Saqz (App Store + Google Play).
# Tudo entra no GitHub Environment "mobile" de bruno-halmeida/saqz.
# ──────────────────────────────────────────────────────────────────────────

REPO="bruno-halmeida/saqz"
GH_ENV="mobile"
GCP_PROJECT="saquz-app"
PLAY_PACKAGE="app.saqz"
SAQZ_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"

# Memória de re-execução fora do repositório (o .env da raiz é do servidor).
# Guarda só ids, aliases e caminhos; senha e chave nunca são gravadas aqui.
ENV_FILE="${ENV_FILE:-$HOME/.config/saqz/mobile-ci.env}"
mkdir -p "$(dirname "$ENV_FILE")"
touch "$ENV_FILE" && chmod 600 "$ENV_FILE"

# set_env_secret NAME VALUE: igual a set_secret, mas no Environment "mobile".
set_env_secret() {
  local name="$1" value="$2"
  if printf '%s' "$value" | gh secret set "$name" --repo "$REPO" --env "$GH_ENV" >/dev/null 2>&1; then
    WRITTEN_SECRET+=("$name")
    printf '  %s✓ gravado%s secret %s (environment %s)\n' "$GREEN" "$RESET" "$name" "$GH_ENV"
  else
    SKIPPED+=("secret $name (gh secret set $name --repo $REPO --env $GH_ENV)")
    warn "não gravei o secret $name; grave depois à mão"
  fi
}

# set_env_secret_file NAME PATH: o conteúdo do arquivo vira o secret, tal qual.
set_env_secret_file() { set_env_secret "$1" "$(cat "$2")"; }

# set_env_secret_b64 NAME PATH: arquivo binário (jks, plist) em base64 numa linha.
set_env_secret_b64() { set_env_secret "$1" "$(openssl base64 -A -in "$2")"; }

# ask_path KEY "Prompt": como ask, mas expande ~ e exige que o arquivo exista.
ask_path() {
  local key="$1" prompt="$2" value
  while true; do
    ask "$key" "$prompt"
    value="${!key/#\~/$HOME}"
    if [[ -f "$value" ]]; then printf -v "$key" '%s' "$value"; return; fi
    warn "não achei o arquivo: $value"
  done
}

# play_api_probe JSON_PATH: assina um JWT com a chave da conta de serviço e tenta
# abrir (e apagar em seguida) uma edição vazia do app no Play. Sucesso significa
# que a permissão dada no Play Console já vale na API, seja qual for o status
# mostrado na lista de usuários.
play_api_probe() {
  local json="$1" email key header claim sig now token resp code edit_id
  email=$(python3 -c 'import json,sys;print(json.load(open(sys.argv[1]))["client_email"])' "$json") || return 1
  key=$(mktemp); chmod 600 "$key"
  python3 -c 'import json,sys;sys.stdout.write(json.load(open(sys.argv[1]))["private_key"])' "$json" > "$key" || { rm -f "$key"; return 1; }
  _b64url() { openssl base64 -A | tr '+/' '-_' | tr -d '='; }
  now=$(date +%s)
  header=$(printf '{"alg":"RS256","typ":"JWT"}' | _b64url)
  claim=$(printf '{"iss":"%s","scope":"https://www.googleapis.com/auth/androidpublisher","aud":"https://oauth2.googleapis.com/token","iat":%d,"exp":%d}' \
    "$email" "$now" $((now + 600)) | _b64url)
  sig=$(printf '%s.%s' "$header" "$claim" | openssl dgst -sha256 -sign "$key" | _b64url)
  rm -f "$key"
  token=$(curl -s https://oauth2.googleapis.com/token \
    --data-urlencode 'grant_type=urn:ietf:params:oauth:grant-type:jwt-bearer' \
    --data-urlencode "assertion=$header.$claim.$sig" \
    | python3 -c 'import json,sys;print(json.load(sys.stdin).get("access_token",""))') || return 1
  [[ -n "$token" ]] || { warn "não consegui um token OAuth com essa chave"; return 1; }
  resp=$(curl -s -w '\n%{http_code}' -X POST -H "Authorization: Bearer $token" -H 'Content-Length: 0' \
    "https://androidpublisher.googleapis.com/androidpublisher/v3/applications/$PLAY_PACKAGE/edits")
  code="${resp##*$'\n'}"
  if [[ "$code" == "200" ]]; then
    edit_id=$(printf '%s' "${resp%$'\n'*}" | python3 -c 'import json,sys;print(json.load(sys.stdin).get("id",""))')
    [[ -n "$edit_id" ]] && curl -s -o /dev/null -X DELETE -H "Authorization: Bearer $token" \
      "https://androidpublisher.googleapis.com/androidpublisher/v3/applications/$PLAY_PACKAGE/edits/$edit_id"
    return 0
  fi
  warn "a API do Play respondeu HTTP $code: $(printf '%s' "${resp%$'\n'*}" | tr -d '\n' | cut -c1-160)"
  return 1
}

TOTAL_STAGES=6

banner "Saqz · segredos do CI de lojas"

# ── 1. Pré-requisitos ─────────────────────────────────────────────────────
stage "GitHub: gh autenticado e Environment \"$GH_ENV\""
say "Os segredos vão para o Environment \"$GH_ENV\" do repositório $REPO."
say "Ele é separado do \"dev\" do backend para nenhum workflow de servidor enxergar chave de loja."
if ! command -v gh >/dev/null 2>&1 || ! gh auth status >/dev/null 2>&1; then
  warn "o gh não está autenticado. Rode 'gh auth login' em outra aba e volte."
  pause "Pronto?"
fi
if gh api "repos/$REPO/environments/$GH_ENV" >/dev/null 2>&1; then
  say "Environment \"$GH_ENV\" já existe."
else
  gh api -X PUT "repos/$REPO/environments/$GH_ENV" >/dev/null
  printf '  %s✓ criado%s Environment %s\n' "$GREEN" "$RESET" "$GH_ENV"
fi
for tool in keytool openssl python3 plutil; do
  command -v "$tool" >/dev/null 2>&1 || warn "faltou '$tool' no PATH; a validação que depende dele será pulada"
done
pause

# ── 2. Apple: chave da App Store Connect API ──────────────────────────────
stage "Apple: chave da App Store Connect API"
say "Com ela o CI assina na nuvem, sobe ao TestFlight e submete à revisão. Nenhum certificado vai para o GitHub."
open_url "https://appstoreconnect.apple.com/access/integrations/api"
step "Em Integrations › App Store Connect API › Team Keys, veja se já existe uma chave com papel App Manager ou Admin que você ainda tenha o .p8 (o arquivo só baixa uma vez)."
note "Há um AuthKey_84TQ7Y6QFG.p8 em ~/Downloads. Se o ID 84TQ7Y6QFG aparecer nessa lista, é uma chave de API e pode ser reaproveitada; se não aparecer, é a chave APNs do Firebase e NÃO serve aqui."
step "Se não houver, clique em (+) Generate API Key: nome 'GitHub Actions', acesso App Manager. Baixe o AuthKey_XXXXXXXXXX.p8."
step "Copie o Issuer ID (topo da página) e o Key ID da linha da chave."
ask ASC_ISSUER_ID "Issuer ID:"
ask ASC_KEY_ID "Key ID:"
ask_path ASC_KEY_P8_PATH "Caminho do arquivo .p8 (ex.: ~/Downloads/AuthKey_${ASC_KEY_ID}.p8):"
if ! head -n1 "$ASC_KEY_P8_PATH" | grep -q 'BEGIN PRIVATE KEY'; then
  warn "esse arquivo não começa com '-----BEGIN PRIVATE KEY-----'; confira se é mesmo o .p8"
  confirm "Gravar assim mesmo?" || { warn "pulando a Apple; rode de novo depois"; ASC_SKIP=1; }
fi
if [[ -z "${ASC_SKIP:-}" ]]; then
  write_env ASC_ISSUER_ID "$ASC_ISSUER_ID"
  write_env ASC_KEY_ID "$ASC_KEY_ID"
  write_env ASC_KEY_P8_PATH "$ASC_KEY_P8_PATH"
  set_env_secret ASC_ISSUER_ID "$ASC_ISSUER_ID"
  set_env_secret ASC_KEY_ID "$ASC_KEY_ID"
  set_env_secret_file ASC_KEY_P8 "$ASC_KEY_P8_PATH"
  note "Guarde o .p8 fora de ~/Downloads (ex.: ~/Projetos/saqz_auth/), com chmod 600."
fi
pause

# ── 3. Google Cloud: conta de serviço do CI ───────────────────────────────
stage "Google Cloud: conta de serviço só para o CI"
say "Uma conta própria, 'github-actions-play', separada da firebase-adminsdk do backend: se vazar, só publica app, não lê o Firebase."
open_url "https://console.cloud.google.com/apis/library/androidpublisher.googleapis.com?project=$GCP_PROJECT"
step "Confira que a Google Play Android Developer API está ativada no projeto $GCP_PROJECT (deve estar, pelas assinaturas). Se não, Enable."
pause
open_url "https://console.cloud.google.com/iam-admin/serviceaccounts/create?project=$GCP_PROJECT"
step "Nome: github-actions-play. Descrição: 'Publica o app Saqz no Play pelo GitHub Actions'. Create and continue."
step "Em 'Grant this service account access to project' NÃO dê papel nenhum (Continue). Done."
step "Na lista, abra github-actions-play@$GCP_PROJECT.iam.gserviceaccount.com › aba Keys › Add key › Create new key › JSON. O arquivo baixa sozinho."
ask_path PLAY_SA_JSON_PATH "Caminho do JSON baixado (ex.: ~/Downloads/${GCP_PROJECT}-xxxxxxxx.json):"
PLAY_SA_EMAIL=$(python3 - "$PLAY_SA_JSON_PATH" <<'PY' 2>/dev/null || true
import json, sys
d = json.load(open(sys.argv[1]))
assert d.get("type") == "service_account"
print(d["client_email"])
PY
)
if [[ -z "$PLAY_SA_EMAIL" ]]; then
  warn "o arquivo não parece uma chave de conta de serviço (type=service_account, client_email)"
  confirm "Gravar assim mesmo?" || { warn "pulando o Play; rode de novo depois"; PLAY_SKIP=1; }
else
  say "Conta de serviço: $PLAY_SA_EMAIL"
fi
if [[ -z "${PLAY_SKIP:-}" ]]; then
  write_env PLAY_SA_JSON_PATH "$PLAY_SA_JSON_PATH"
  write_env PLAY_SA_EMAIL "${PLAY_SA_EMAIL:-}"
  set_env_secret_file PLAY_SERVICE_ACCOUNT_JSON "$PLAY_SA_JSON_PATH"
  note "Mova o JSON para ~/Projetos/saqz_auth/ com chmod 600; ele dá acesso de publicação."
fi
pause

# ── 4. Play Console: permissão de release para a conta ───────────────────
stage "Play Console: convidar a conta de serviço"
say "Sem este passo a API responde 'The caller does not have permission'."
open_url "https://play.google.com/console/"
step "Usuários e permissões › Convidar novos usuários. E-mail: ${PLAY_SA_EMAIL:-github-actions-play@$GCP_PROJECT.iam.gserviceaccount.com}"
step "Em Permissões do app › Adicionar app › Saqz (app.saqz). Marque, no grupo Lançamento:"
step "  - 'Lançar para produção, excluir dispositivos e usar a Assinatura de apps do Google Play'"
step "  - 'Lançar apps nas faixas de teste'"
step "  - 'Gerenciar faixas de teste e editar listas de testadores'"
step "Enviar convite. O status pode ficar em 'Convite enviado': conta de serviço não tem quem aceite, e a API funciona mesmo assim."
if [[ -z "${PLAY_SKIP:-}" ]]; then
  while true; do
    pause "Convite enviado? (Enter testa a permissão na API)"
    say "Testando: abrir e apagar uma edição vazia de $PLAY_PACKAGE em nome da conta…"
    if play_api_probe "$PLAY_SA_JSON_PATH"; then
      printf '  %s✓ a API do Play aceita%s %s\n' "$GREEN" "$RESET" "${PLAY_SA_EMAIL:-a conta}"
      break
    fi
    warn "A permissão pode levar até 24 h para valer. Salvar qualquer rascunho no Console do app costuma destravar."
    confirm "Testar de novo? (N segue sem a confirmação)" || { SKIPPED+=("permissão da conta de serviço no Play Console: a API ainda respondia sem permissão"); break; }
  done
else
  pause "Convite enviado?"
fi

# ── 5. Android: chave de upload ───────────────────────────────────────────
stage "Android: chave de upload (Play App Signing)"
say "A chave que assina o AAB que o CI manda ao Play. O Play reassina com a chave de app dele."
KS_DEFAULT="$HOME/Projetos/saqz_auth/Untitled.jks"
if [[ -f "$KS_DEFAULT" && -z "$(_existing ANDROID_UPLOAD_KEYSTORE_PATH || true)" ]]; then
  note "Encontrei $KS_DEFAULT, a chave que publicou a 0.0.4; Enter aceita."
  write_env ANDROID_UPLOAD_KEYSTORE_PATH "$KS_DEFAULT"
fi
ask_path ANDROID_UPLOAD_KEYSTORE_PATH "Caminho do keystore de upload:"
ask_secret ANDROID_UPLOAD_STORE_PASSWORD "Senha do keystore:"
if command -v keytool >/dev/null 2>&1; then
  if ! keytool -list -keystore "$ANDROID_UPLOAD_KEYSTORE_PATH" -storepass "$ANDROID_UPLOAD_STORE_PASSWORD" >/dev/null 2>&1; then
    warn "senha do keystore recusada"; exit 1
  fi
  aliases=$(keytool -list -keystore "$ANDROID_UPLOAD_KEYSTORE_PATH" -storepass "$ANDROID_UPLOAD_STORE_PASSWORD" 2>/dev/null \
      | grep -E 'PrivateKeyEntry' | cut -d, -f1)
  say "Aliases com chave privada: $(echo "$aliases" | tr '\n' ' ')"
  alias_count=$(echo "$aliases" | grep -c . || true)
  if [[ "$alias_count" -eq 1 ]]; then ANDROID_UPLOAD_KEY_ALIAS="$aliases"; write_env ANDROID_UPLOAD_KEY_ALIAS "$aliases"; fi
fi
ask ANDROID_UPLOAD_KEY_ALIAS "Alias da chave:"
ask_secret ANDROID_UPLOAD_KEY_PASSWORD "Senha da chave (em keystore PKCS12 é a mesma do keystore):"
if command -v keytool >/dev/null 2>&1; then
  probe=$(mktemp -u).p12
  if keytool -importkeystore -srckeystore "$ANDROID_UPLOAD_KEYSTORE_PATH" -srcstorepass "$ANDROID_UPLOAD_STORE_PASSWORD" \
       -srcalias "$ANDROID_UPLOAD_KEY_ALIAS" -srckeypass "$ANDROID_UPLOAD_KEY_PASSWORD" \
       -destkeystore "$probe" -deststoretype PKCS12 -deststorepass "$ANDROID_UPLOAD_STORE_PASSWORD" >/dev/null 2>&1; then
    rm -f "$probe"
    printf '  %s✓ alias e senha da chave conferem%s\n' "$GREEN" "$RESET"
  else
    rm -f "$probe"; warn "alias ou senha da chave recusados"; exit 1
  fi
  sha1=$(keytool -list -v -keystore "$ANDROID_UPLOAD_KEYSTORE_PATH" -storepass "$ANDROID_UPLOAD_STORE_PASSWORD" \
           -alias "$ANDROID_UPLOAD_KEY_ALIAS" 2>/dev/null | grep -E 'SHA1:' | head -n1 | sed 's/^[[:space:]]*//')
  say "Impressão da chave: $sha1"
  open_url "https://play.google.com/console/"
  step "No app Saqz › Configurar › Integridade do app › Assinatura de apps, compare com 'Certificado da chave de upload' › SHA-1."
  confirm "O SHA-1 do Play é o mesmo?" || { warn "esta não é a chave de upload registrada; o Play recusará o AAB. Ache o keystore certo e rode de novo."; exit 1; }
fi
write_env ANDROID_UPLOAD_KEYSTORE_PATH "$ANDROID_UPLOAD_KEYSTORE_PATH"
write_env ANDROID_UPLOAD_KEY_ALIAS "$ANDROID_UPLOAD_KEY_ALIAS"
set_env_secret_b64 ANDROID_UPLOAD_KEYSTORE_B64 "$ANDROID_UPLOAD_KEYSTORE_PATH"
set_env_secret ANDROID_UPLOAD_STORE_PASSWORD "$ANDROID_UPLOAD_STORE_PASSWORD"
set_env_secret ANDROID_UPLOAD_KEY_ALIAS "$ANDROID_UPLOAD_KEY_ALIAS"
set_env_secret ANDROID_UPLOAD_KEY_PASSWORD "$ANDROID_UPLOAD_KEY_PASSWORD"
pause

# ── 6. Firebase: arquivos de produção ─────────────────────────────────────
stage "Firebase: google-services.json e GoogleService-Info.plist de produção"
say "Os dois ficam fora do git. O CI os recria a partir destes secrets antes de buildar."
GS_JSON="$SAQZ_ROOT/mobile/android-app/src/prod/google-services.json"
GS_PLIST="$SAQZ_ROOT/mobile/ios-app/SaqzIOS/Config/Prod/GoogleService-Info.plist"
ok=1
if [[ -f "$GS_JSON" ]]; then
  pid=$(python3 -c "import json,sys;print(json.load(open(sys.argv[1]))['project_info']['project_id'])" "$GS_JSON" 2>/dev/null || true)
  [[ "$pid" == "$GCP_PROJECT" ]] && say "google-services.json: projeto $pid ✓" || { warn "google-services.json aponta para '$pid', esperava $GCP_PROJECT"; ok=0; }
else
  warn "não achei $GS_JSON"; ok=0
fi
if [[ -f "$GS_PLIST" ]]; then
  pid=$(plutil -extract PROJECT_ID raw "$GS_PLIST" 2>/dev/null || true)
  [[ "$pid" == "$GCP_PROJECT" ]] && say "GoogleService-Info.plist: projeto $pid ✓" || { warn "plist aponta para '$pid', esperava $GCP_PROJECT"; ok=0; }
else
  warn "não achei $GS_PLIST"; ok=0
fi
if [[ "$ok" -eq 1 ]] || confirm "Há divergência acima. Gravar assim mesmo?"; then
  set_env_secret_b64 FIREBASE_GOOGLE_SERVICES_JSON_B64 "$GS_JSON"
  set_env_secret_b64 FIREBASE_GOOGLE_SERVICE_INFO_PLIST_B64 "$GS_PLIST"
fi
printf '\n'
say "Secrets no Environment $GH_ENV agora:"
gh secret list --repo "$REPO" --env "$GH_ENV" 2>/dev/null | sed 's/^/    /' || true
pause

finish
